 * @returns {string[]}
 */
export function buildOpenCodeCliArgs(input) {
  const cliArgs = ['run', input.prompt, '--format', 'json'];
  if (input.model) {
    cliArgs.push('--model', input.model);
  } else if (input.modelPolicy === 'native-default') {
