@keyframes pulse {
  0%,
  100% {
    opacity: 1;
  }
  50% {
    opacity: 0.5;
  }
}

/* ----------------------------------------------------------------------------
   View transitions
   See: https://react.dev/reference/react/ViewTransition
   ------------------------------------------------------------------------- */

:root {
  --duration-exit: 150ms;
  --duration-enter: 210ms;
  --duration-move: 400ms;
  --slide-offset: 60px;
}

/* Keep the page clickable while a transition runs: the ::view-transition
   overlay otherwise swallows pointer events for the animation's duration. */
::view-transition {
  pointer-events: none;
}

/* --- Shared element morph (thumbnail <-> hero) ----------------------------- */
/* `share="morph"` assigns the `morph` view-transition-class. A soft blur
   mid-flight hides pixel-level interpolation artifacts as the image resizes. */
::view-transition-group(.morph) {
  animation-duration: var(--duration-move);
}
::view-transition-image-pair(.morph) {
  animation: var(--duration-move) ease-in-out both via-blur;
}
@keyframes via-blur {
  30% {
    filter: blur(3px);
  }
}

/* --- Suspense reveal (skeleton -> content) --------------------------------- */
/* The fallback exits (slides down + fades out fast), then the content enters
   (slides up + fades in, delayed until the fallback has left). */
::view-transition-old(.slide-down) {
  animation:
    var(--duration-exit) ease-out both fade reverse,
    var(--duration-exit) ease-out both slide-y reverse;
}
::view-transition-new(.slide-up) {
  animation:
    var(--duration-enter) ease-in var(--duration-exit) both fade,
    var(--duration-move) ease-in both slide-y;
}
@keyframes fade {
  from {
    filter: blur(3px);
    opacity: 0;
  }
  to {
    filter: blur(0);
    opacity: 1;
  }
}
@keyframes slide-y {
  from {
    transform: translateY(10px);
  }
  to {
    transform: translateY(0);
  }
}

/* --- Directional navigation (forward / back) ------------------------------- */
/* Forward: old content slides left out, new content slides in from the right.
   Back: the reverse. The 60px offset signals direction without dragging the
   eye across the viewport. */
::view-transition-old(.nav-forward) {
  --slide-offset: calc(-1 * 60px);
  animation:
    var(--duration-exit) ease-in both fade reverse,
    var(--duration-move) ease-in-out both slide reverse;
}
::view-transition-new(.nav-forward) {
  --slide-offset: 60px;
  animation:
    var(--duration-enter) ease-out var(--duration-exit) both fade,
    var(--duration-move) ease-in-out both slide;
}
::view-transition-old(.nav-back) {
  --slide-offset: 60px;
  animation:
    var(--duration-exit) ease-in both fade reverse,
    var(--duration-move) ease-in-out both slide reverse;
}
::view-transition-new(.nav-back) {
  --slide-offset: calc(-1 * 60px);
  animation:
    var(--duration-enter) ease-out var(--duration-exit) both fade,
    var(--duration-move) ease-in-out both slide;
}
@keyframes slide {
  from {
    translate: var(--slide-offset);
  }
  to {
    translate: 0;
  }
}

/* --- Reduced motion -------------------------------------------------------- */
/* Disable positional movement and opacity/filter animations for users who
   prefer reduced motion. Content swaps instantly (the browser default). The
   pulse skeleton shimmer is also removed. */
@media (prefers-reduced-motion: reduce) {
  ::view-transition-old(*),
  ::view-transition-new(*),
  ::view-transition-group(*) {
    animation-duration: 0s !important;
    animation-delay: 0s !important;
  }

  .skeleton-image,
  .skeleton-text {
    animation: none !important;
  }
}

